import {max, min} from 'd3-array';
import {scaleBand, scaleLinear} from 'd3-scale';
import {line as d3Line} from 'd3-shape';
import {useEffect, useRef, useState, useMemo} from 'react';
import type {ValueTimecode} from './types';
import {timeToSecs} from './utils';

interface ChartProps {
  data: ValueTimecode[];
  yLabel: string;
  jumpToTimecode: (time: number) => void;
}

export default function Chart({data, yLabel, jumpToTimecode}: ChartProps) {
  const chartRef = useRef<SVGSVGElement>(null);
  const [width, setWidth] = useState(1);
  const [height, setHeight] = useState(1);
  const margin = 55;
  const xMax = width;
  const yMax = height - margin;

  const { xScale, yScale, lineGen, yTicks } = useMemo(() => {
    const xScale = scaleBand<string>()
        .range([margin + 10, xMax])
        .domain(data.map((d) => d.time))
        .padding(0.2);

    const vals = data.map((d) => d.value);
    const yScale = scaleLinear()
        .domain([min(vals) ?? 0, max(vals) ?? 10])
        .nice()
        .range([yMax, margin]);

    const yTicks = yScale.ticks(Math.floor(height / 70));

    const lineGen = d3Line<ValueTimecode>()
        .x((d) => xScale(d.time) ?? 0)
        .y((d) => yScale(d.value));

    return { xScale, yScale, lineGen, yTicks };
  }, [data, width, height, xMax, yMax, margin]);

  useEffect(() => {
    const setSize = () => {
      if (chartRef.current) {
        setWidth(chartRef.current.clientWidth);
        setHeight(chartRef.current.clientHeight);
      }
    };

    setSize();
    const resizeObserver = new ResizeObserver(setSize);
    if (chartRef.current) {
      resizeObserver.observe(chartRef.current);
    }
    return () => resizeObserver.disconnect();
  }, []);

  const handleTimecodeActivation = (time: string) => {
    jumpToTimecode(timeToSecs(time));
  };

  return (
    <svg className="lineChart" ref={chartRef}>
      <g className="axisLabels" transform={`translate(0 ${0})`}>
        {yTicks.map((tick) => {
          const y = yScale(tick);

          return (
            <g key={tick} transform={`translate(0 ${y})`}>
              <text x={margin - 10} dy="0.25em" textAnchor="end">
                {tick}
              </text>
            </g>
          );
        })}
      </g>

      <g
        className="axisLabels timeLabels"
        transform={`translate(0 ${yMax + 40})`}>
        {data.map(({time}, i) => {
          return (
            <text
              key={i}
              x={xScale(time)}
              role="button"
              tabIndex={0}
              onClick={() => handleTimecodeActivation(time)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  handleTimecodeActivation(time);
                }
              }}>
              {time.length > 5 ? time.replace(/^00:/, '') : time}
            </text>
          );
        })}
      </g>

      <g>
        <path d={lineGen(data) ?? ''} />
      </g>

      <g>
        {data.map(({time, value}, i) => {
          return (
            <g key={i} className="dataPoint">
              <circle cx={xScale(time)} cy={yScale(value)} r={4} />

              <text x={xScale(time)} y={yScale(value) - 12}>
                {value}
              </text>
            </g>
          );
        })}
      </g>

      <text
        className="axisTitle"
        x={margin}
        y={-width + margin}
        transform="rotate(90)">
        {yLabel}
      </text>
    </svg>
  );
}

